window.AUTH=window.AUTH||{};window.AUTH["19-8709"]={"d":"19-8709","id":"2020/19-8709","n":"Greer v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Gregory Greer","date":"2021-02-22","url":"https://www.supremecourt.gov/DocketPDF/19/19-8709/169605/20210222171108435_Greer%20Merits%20Brief%20Final.pdf","side":"pet","n":78},{"k":"respondent","label":"Brief of respondent United States of America","date":"2021-03-24","url":"https://www.supremecourt.gov/DocketPDF/19/19-8709/172890/20210324163945837_19-8709bsUnitedStates.pdf","side":"res","n":67},{"k":"reply","label":"Reply of petitioner Gregory Greer","date":"2021-04-09","url":"https://www.supremecourt.gov/DocketPDF/19/19-8709/175325/20210409130042095_Greer%20Merits%20Reply%20in%20Shell_FINAL.pdf","side":"pet","n":36}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/593us2r46_1qm2.pdf","tr":true,"items":[{"t":"case","label":"Arizona v. Fulminante","cite":"499 U.S. 279","y":1991,"id":"1990/89-839","sc":1,"by":{"0":"14","1":"30, 31"},"q":[{"src":"brief","b":0,"text":"be quantitatively assessed in the context of other evidence presented","cite":"499 U.S. 279, 307–08"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"entire conduct of the [proceeding] from beginning to end.","cite":"499 U. S., at 309"}]},{"t":"case","label":"Blakely v. Washington","cite":"542 U.S. 296","y":2004,"id":"2003/02-1632","sc":1,"by":{"0":"21"},"q":[{"src":"brief","b":0,"text":"finding the facts essential to lawful imposition of the penalty.","cite":"542 U.S. at 309"}]},{"t":"case","label":"Betterman v. Montana","cite":"136 S. Ct. 1609","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./136/1609/","sc":1,"by":{"0":"35"}},{"t":"case","label":"Burks v. United States","cite":"437 U.S. 1","y":1978,"id":"1977/76-6528","sc":1,"by":{"0":"15"}},{"t":"case","label":"Clyatt v. United States","cite":"197 U.S. 207","y":1905,"id":"scdb/1904-129","sc":1,"by":{"0":"12, 40","1":"29","2":"2, 4"},"q":[{"src":"brief","b":0,"text":"No matter how severe may be the condemnation which is due to the conduct of a party charged with a criminal offense, it is the imperative duty of a court to see that all the elements of his crime are proved, or at least that testimony is offered which justifies a jury in finding those elements.","cite":"197 U.S. at 222"},{"src":"argument","who":"Ms. Guagliardo","text":"And with an insufficiency claim, the question is -- and this goes back to the Court's earliest cases, such as in Clyatt and Wiborg -- what was the information or the evidence introduced before the fact-finder?"},{"src":"argument","who":"Ms. Guagliardo","text":"No, the -- the -- prongs 3 and 4 do not automatically collapse, but it is true that given the nature of the error, when the nature of the error is the insufficient evidence of the defendant's guilt at his trial, some courts, including some of the court -- this Court's earliest cases in Wiborg and Clyatt and other circuit appellate courts, have said there in the ordinary case then, prongs -- if -- if, at prong 3, the outcome has been affected, then that case may ordinarily meet prong 4."}]},{"t":"case","label":"Crawford v. Washington","cite":"541 U.S. 36","y":2004,"id":"2003/02-9410","sc":1,"by":{"0":"23"},"q":[{"src":"brief","b":0,"text":"commands, not that evidence be reliable, but that reliability be assessed in a particular manner: by testing in the crucible of cross-examination.","cite":"541 U.S. 36, 61"}]},{"t":"case","label":"Cunningham v. California","cite":"549 U.S. 270","y":2007,"id":"2006/05-6551","sc":1,"by":{"0":"37"}},{"t":"case","label":"Descamps v. United States","cite":"570 U.S. 254","y":2013,"id":"2012/11-9540","sc":1,"by":{"0":"23","2":"8, 9"}},{"t":"case","label":"Duncan v. Louisiana","cite":"391 U.S. 145","y":1968,"id":"1967/410","sc":1,"by":{"0":"20, 21"},"q":[{"src":"brief","b":0,"text":"fundamental to the American scheme of justice.","cite":"391 U.S. 145, 148–50"}]},{"t":"case","label":"Dunn v. United States","cite":"442 U.S. 100","y":1979,"id":"1978/77-6949","sc":1,"by":{"0":"31","2":"8"},"q":[{"src":"brief","b":0,"text":"appellate courts are not free to revise the basis on which a defendant is convicted simply because the same result would likely obtain on retrial.","cite":"442 U.S. 100, 107"}]},{"t":"case","label":"Esquivel-Quintana v. Sessions","cite":"137 S. Ct. 1562","y":2017,"id":"2016/16-54","sc":1,"by":{"0":"13"}},{"t":"case","label":"Greer v. United States","cite":"140 S. Ct. 41","y":2019,"url":"https://www.courtlistener.com/c/S.%20Ct./140/41/","sc":1,"by":{"0":"1"}},{"t":"case","label":"Gregg v. United States","cite":"394 U.S. 489","y":1969,"id":"1968/453","sc":1,"by":{"0":"36, 37"}},{"t":"case","label":"Griffith v. Kentucky","cite":"479 U.S. 314","y":1987,"id":"1986/85-5221","sc":1,"by":{"0":"5, 33, 34"},"q":[{"src":"brief","b":0,"text":"retroactively to all cases . . . pending on direct review.","cite":"479 U.S. 314, 328"}]},{"t":"case","label":"Hankerson v. North Carolina","cite":"432 U.S. 233","y":1977,"id":"1976/75-6568","sc":1,"by":{"0":"22"},"q":[{"src":"brief","b":0,"text":"to prevent the erroneous conviction of innocent persons.","cite":"432 U.S. 233, 239"}]},{"t":"case","label":"Hicks v. United States","cite":"137 S. Ct. 2000","y":2017,"url":"https://www.courtlistener.com/c/S.%20Ct./137/2000/","sc":1,"by":{"0":"41","2":"11, 12"}},{"t":"case","label":"Holmes v. South Carolina","cite":"547 U.S. 319","y":2006,"id":"2005/04-1327","sc":1,"by":{"0":"23"},"q":[{"src":"brief","b":0,"text":"meaningful opportunity to present a complete defense.","cite":"547 U.S. 319, 324"}]},{"t":"case","label":"Joseph v. United States","cite":"135 S. Ct. 705","y":2014,"url":"https://www.courtlistener.com/c/S.%20Ct./135/705/","sc":1,"by":{"0":"33"}},{"t":"case","label":"Johnson v. United States","cite":"520 U.S. 461","y":1997,"id":"1996/96-203","sc":1,"by":{"0":"30","1":"passim","2":"8, 12, 13"},"q":[{"src":"brief","b":0,"text":"In applying the fourth prong of Olano’s harmless error test, we follow the Court in Johnson which considered whether the evidence on the element was ‘overwhelming’ and ‘essentially uncontroverted at trial.’","cite":"520 U.S. at 470"},{"src":"brief","b":1,"text":"(1) ‘error,’ (2) that is ‘plain,’ and (3) that ‘affect[s] substantial rights.’","cite":"520 U.S. 461, 466467"},{"src":"brief","b":1,"text":"the error ‘seriously affect[s] the fairness, integrity, or public reputation of judicial proceedings.’","cite":"520 U.S. at 467"}]},{"t":"case","label":"Leland v. Oregon","cite":"343 U.S. 790","y":1952,"id":"scdb/1951-094","sc":1,"by":{"0":"22"}},{"t":"case","label":"Lewis v. United States","cite":"146 U.S. 370","y":1892,"id":"scdb/1892-037","sc":1,"by":{"0":"23"}},{"t":"case","label":"Marshall v. United States","cite":"360 U.S. 310","y":1959,"id":"1958/383","sc":1,"by":{"0":"24"}},{"t":"case","label":"McCormick v. United States","cite":"500 U.S. 257","y":1991,"id":"1990/89-1918","sc":1,"by":{"0":"22"}},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"by":{"0":"22, 25"},"q":[{"src":"brief","b":0,"text":"Where intent of the accused is an ingredient of the crime charged, its existence is a question of fact which must be submitted to the jury.","cite":"342 U.S. at 274"}]},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"by":{"0":"passim","1":"10, 17, 30, 33, 34","2":"passim"},"q":[{"src":"brief","b":0,"text":"did not contribute to the verdict obtained.","cite":"527 U.S. 1, 16–17"},{"src":"brief","b":0,"text":"right to render the verdict in criminal prosecutions belongs exclusively to the jury; reviewing it belongs to the appellate court.","cite":"527 U.S. at 38"},{"src":"brief","b":1,"text":"record evidence of guilt the jury did not actually consider.","cite":"527 U.S. at 17"},{"src":"brief","b":1,"text":"does not fundamentally undermine the purposes of the jury trial guarantee.","cite":"527 U.S. at 19"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"necessarily render a criminal trial fundamentally unfair or an unreliable vehicle for determining guilt or innocence.","cite":"527 U. S., at 9"},{"src":"argument","who":"Justice Sotomayor","text":"Counsel, I think Justice Scalia would have agreed with you in his -- by his dissent in Neder. But putting that aside, I have two questions that I hope you'll get to in my time."},{"src":"argument","who":"Ms. Guagliardo","text":"Your Honor, what has happened here goes well beyond what happened in Neder, for example. In Neder, there -- there was a fact-finder on all of the elements of the offense."},{"src":"argument","who":"Justice Gorsuch","text":"Well, I'm -- I'm really not so concerned about Neder as the principle that we often conduct as appellate judges a prejudice analysis of trial court errors, and we don't think of that as usurping the Sixth Amendment function of the jury because we're dealing with a forfeited error."}]},{"t":"case","label":"Patterson v. New York","cite":"432 U.S. 197","y":1977,"id":"1976/75-1861","sc":1,"by":{"0":"22"}},{"t":"case","label":"Pope v. Illinois","cite":"481 U.S. 497","y":1987,"id":"1986/85-1973","sc":1,"by":{"0":"15","1":"30"},"q":[{"src":"brief","b":0,"text":"the record developed at trial established guilt beyond a reasonable doubt","cite":"481 U.S. 497, 502–03"}]},{"t":"case","label":"Rehaif v. United States","cite":"139 S. Ct. 2191","y":2019,"id":"2018/17-9560","sc":1,"by":{"0":"1, 2, 4","1":"2, 7, 11, 12, 34, 39","2":"4, 15"},"q":[{"src":"brief","b":1,"text":"knowledge [of his felon status] can be inferred,","cite":"139 S. Ct. at 2198"},{"src":"argument","who":"Ms. Guagliardo","text":"That is particularly the case here, where, because of the uniform circuit precedent before Rehaif, at no proceeding in the district court had the parties addressed or the judge found the mens rea required by this Court in Rehaif."},{"src":"argument","who":"Chief Justice Roberts","text":"Let's suppose you have a defendant who is convicted under 922(g) prior to Rehaif and, on appeal, she argues that if she had known she had to establish or the prosecution had to establish a felon -- that she knew that she was a felon, that she would have introduced mental health evidence to show that she was incapable of that knowledge."},{"src":"argument","who":"Ms. Guagliardo","text":"Your Honor, it -- with respect to the scope, it will just depend case by case did the government establish the defendant's guilt at trial, and it's really just a function of the fact that the -- the uniform precedent has now been overturned by Rehaif because the -- that precedent had turned out to be incorrect."}]},{"t":"case","label":"Rock v. Arkansas","cite":"483 U.S. 44","y":1987,"id":"1986/86-130","sc":1,"by":{"0":"24"}},{"t":"case","label":"Rosales-Mireles v. United States","cite":"138 S. Ct. 1897","y":2018,"id":"2017/16-9493","sc":1,"by":{"0":"15","1":"42","2":"5, 7, 11"},"q":[{"src":"brief","b":1,"text":"require[] additional jury proceedings on remand.","cite":"138 S. Ct. 1897, 1909"},{"src":"argument","who":"Ms. Guagliardo","text":"There -- the Court, such as in Rosales-Mireles, had left open the possibility that, although that's a guideline error case, the Court stated that ordinarily such an error would meet prongs 3 and 4."},{"src":"argument","who":"Mr. Snyder","text":"And in Rosales-Mireles, the Court looked to a compilation of psychology research in answering how the error at issue there would affect public perceptions of the proceedings."}]},{"t":"case","label":"Shepard v. United States","cite":"544 U.S. 13","y":2005,"id":"2004/03-9168","sc":1,"by":{"0":"36"}},{"t":"case","label":"Sparf v. United States","cite":"156 U.S. 51","y":1895,"id":"scdb/1894-076","sc":1,"by":{"0":"25, 26"}},{"t":"case","label":"Sullivan v. Louisiana","cite":"508 U.S. 275","y":1993,"id":"1992/92-5129","sc":1,"by":{"0":"passim","1":"29, 30","2":"10"},"q":[{"src":"brief","b":0,"text":"is not what effect the constitutional error might generally be expected to have upon a reasonable jury, but rather what effect it had upon the guilty verdict in the case at hand.","cite":"508 U.S. at 279"},{"src":"brief","b":0,"text":"right includes, of course, as its most important element, the right to have the jury, rather than the judge, reach the requisite finding of ‘guilty.’","cite":"508 U.S. at 277"},{"src":"brief","b":2,"text":"not what effect the constitutional error might generally be expected to have upon a reasonable jury, but rather what effect it had upon the guilty verdict in the case at hand.","cite":"508 U.S. 275, 279"}]},{"t":"case","label":"United States v. Booker","cite":"543 U.S. 220","y":2005,"id":"2004/04-104","sc":1,"by":{"0":"37"}},{"t":"case","label":"United States v. Brasfield","cite":"272 U.S. 448","y":1926,"id":"scdb/1926-005","sc":1,"by":{"0":"41"}},{"t":"case","label":"United States v. Ceron","cite":"775 F.3d 222","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/775/222/","by":{"0":"34","1":"32"}},{"t":"case","label":"United States v. Conti","cite":"804 F.3d 977","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/804/977/","by":{"0":"34","1":"32"}},{"t":"case","label":"United States v. Cotton","cite":"535 U.S. 625","y":2002,"id":"2001/01-687","sc":1,"by":{"0":"30","1":"11, 23, 24, 31, 42"},"q":[{"src":"brief","b":1,"text":"real threat * * * to the ‘fairness, integrity, and public reputation of judicial proceedings,’","cite":"535 U.S. at 634"}]},{"t":"case","label":"United States v. Delgado","cite":"672 F.3d 320","y":2012,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/672/320/","by":{"0":"27"},"q":[{"src":"brief","b":0,"text":"at least at times, . . . application of the plain-error standard has little practical impact because a conviction on constitutionally insufficient evidence will almost always satisfy the third and fourth prongs of the test.","cite":"672 F.3d 320, 331–32"}]},{"t":"case","label":"United States v. Dominguez Benitez","cite":"542 U.S. 74","y":2004,"id":"2003/03-167","sc":1,"by":{"0":"17, 19","1":"8, 14, 15, 16, 20","2":"5"},"q":[{"src":"brief","b":1,"text":"‘a reasonable probability that, but for the error,’ the outcome of his proceeding would have been different.","cite":"542 U.S. 74, 76"},{"src":"brief","b":1,"text":"a reasonable probability that, but for [the error claimed], the result of the proceeding would have been different,","cite":"542 U.S. at 82"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"the burden of establishing entitlement to relief for plain error.","cite":"542 U. S. 74, 82"}]},{"t":"case","label":"United States v. Duran","cite":"133 F.3d 1324","y":1998,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/133/1324/","by":{"0":"27"}},{"t":"case","label":"United States v. Figueroa","cite":"683 F.3d 69","y":2012,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/683/69/","by":{"0":"24"}},{"t":"case","label":"United States v. Gaudin","cite":"515 U.S. 506","y":1995,"id":"1994/94-514","sc":1,"by":{"0":"21"}},{"t":"case","label":"United States v. Gaydos","cite":"108 F.3d 505","y":1997,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/108/505/","by":{"0":"27"}},{"t":"case","label":"United States v. Hall","cite":"610 F.3d 727","y":2010,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/610/727/","by":{"0":"34","1":"32"}},{"t":"case","label":"United States v. Haymond","cite":"139 S. Ct. 2369","y":2019,"id":"2018/17-1672","sc":1,"by":{"0":"21, 22, 40, 41"},"q":[{"src":"brief","b":0,"text":"ensure that the government must prove to a jury every criminal charge beyond a reasonable doubt, an ancient rule that has ‘extend[ed] down centuries.’","cite":"139 S. Ct. at 2376"},{"src":"brief","b":0,"text":"[T]he jury system isn’t designed to promote efficiency but to protect liberty.","cite":"139 S. Ct. at 2384"}]},{"t":"case","label":"United States v. Houston","cite":"792 F.3d 663","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/792/663/","by":{"0":"26"}},{"t":"case","label":"United States v. Johnson","cite":"821 F.3d 1194","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/821/1194/","by":{"0":"27","2":"19"},"q":[{"src":"brief","b":2,"text":"a successful sufficiency challenge almost always meets the first three factors of plain error and will generally meet the fourth.","cite":"821 F.3d 1194, 1203"}]},{"t":"case","label":"United States v. Lane","cite":"474 U.S. 438","y":1986,"id":"1985/84-744","sc":1,"by":{"0":"10"}},{"t":"case","label":"United States v. Lockhart","cite":"947 F.3d 187","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/947/187/","by":{"0":"38","1":"38"},"q":[{"src":"brief","b":1,"text":"was prejudiced by the Rehaif error,","cite":"947 F.3d 187, 196"}]},{"t":"case","label":"United States v. Maez","cite":"960 F.3d 949","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/960/949/","by":{"0":"18","1":"25"},"q":[{"src":"brief","b":0,"text":"[t]he same logic does not apply to trial errors,","cite":"960 F.3d 949, 960"}]},{"t":"case","label":"United States v. Makkar","cite":"810 F.3d 1139","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/810/1139/","by":{"0":"40","2":"11"}},{"t":"case","label":"United States v. Marcus","cite":"560 U.S. 258","y":2010,"id":"2009/08-1341","sc":1,"by":{"0":"10","2":"13"},"q":[{"src":"argument","who":"Ms. Guagliardo","text":"And in Johnson, the Court was able to affirm based on the overwhelming evidence on the element before the fact-finder at the trial, and so -- and in the later case of Marcus, for example, the Court addressed the fact that that was such an instance where the verdict had not undermined the fairness, integrity, and reputation of proceedings, and that was because the evidence at the trial had been --"}]},{"t":"case","label":"United States v. Martinez","cite":"136 F.3d 972","y":1998,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/136/972/","by":{"0":"34","1":"32"}},{"t":"case","label":"United States v. McDonald","cite":"336 F.3d 734","y":2003,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/336/734/","by":{"0":"34","1":"32"}},{"t":"case","label":"United States v. Mechanik","cite":"475 U.S. 66","y":1986,"id":"1985/84-1640","sc":1,"by":{"0":"15","1":"17, 18, 31","2":"6"},"q":[{"src":"brief","b":0,"text":"error[s] occurring in the criminal trial itself.","cite":"475 U.S. 66, 71–72"}]},{"t":"case","label":"United States v. Nasir","cite":"982 F.3d 144","y":2020,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/982/144/","by":{"0":"passim","1":"22, 23, 32, 38","2":"passim"},"q":[{"src":"brief","b":0,"text":"a procedural posture that is completely unlike the review of a conviction following trial.","cite":"982 F.3d 144, 166"},{"src":"brief","b":0,"text":"the information presented to the trier of fact—in this case, the jury.","cite":"982 F.3d at 166"},{"src":"brief","b":1,"text":"the Court itself * * * found that the record contained enough evidence on materiality that no reasonable juror could have decided the materiality question in any other way.","cite":"982 F.3d 144, 193"},{"src":"brief","b":1,"text":"considered whether [the defendant] made a plausible showing—not just at trial but afterwards","cite":"982 F.3d at 194"},{"src":"brief","b":2,"text":"would give [the reviewing court] free rein to speculate whether the government could have proven each element of the offense beyond a reasonable doubt at a hypothetical trial that established a different trial record.","cite":"982 F.3d 144, 163"}]},{"t":"case","label":"United States v. O’Brien","cite":"560 U.S. 218","y":2010,"id":"2009/08-1569","sc":1,"by":{"0":"37"}},{"t":"case","label":"United States v. Olano","cite":"507 U.S. 725","y":1993,"id":"1992/91-1306","sc":1,"by":{"0":"passim","1":"passim","2":"passim"},"q":[{"src":"brief","b":0,"text":"to clarify the standard for ‘plain error’ review by the courts of appeals,","cite":"507 U.S. at 731"},{"src":"brief","b":0,"text":"specific analysis of the district court record,","cite":"507 U.S. at 734"},{"src":"brief","b":1,"text":"‘No procedural principle is more familiar to this Court than that a constitutional right,’ or a right of any other sort, ‘may be forfeited in criminal as well as civil cases by the failure to make timely assertion of the right before a tribunal having jurisdiction to determine it.’","cite":"507 U.S. 725, 731"},{"src":"brief","b":1,"text":"the court of appeals has authority to order correction, but [it] is not required to do so.","cite":"507 U.S. at 735"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"Rule 52(b) is permissive, not mandatory.","cite":"507 U. S. 725, 735"},{"src":"argument","who":"Ms. Guagliardo","text":"The second point then I'd like to turn to is from this Court's case in Olano. In Olano, the Court recognized that plain-error relief is not limited to those for whom the appellate court presumes or finds may be innocent."}]},{"t":"case","label":"United States v. Perez-Montanez","cite":"202 F.3d 434","y":2000,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/202/434/","by":{"0":"34","1":"32"}},{"t":"case","label":"United States v. Reed","cite":"941 F.3d 1018","y":2019,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/941/1018/","by":{"0":"16, 17, 19"},"q":[{"src":"brief","b":0,"text":"a reviewing court may consult the whole record when considering the effect of any error on substantial rights.","cite":"941 F.3d at 1021"},{"src":"brief","b":0,"text":"a court reviewing for plain error is ‘informed by the entire record.’","cite":"941 F.3d at 1021"}]},{"t":"case","label":"United States v. Rufai","cite":"732 F.3d 1175","y":2013,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/732/1175/","by":{"0":"27"}},{"t":"case","label":"United States v. Sabillon-Umana","cite":"772 F.3d 1328","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/772/1328/","by":{"0":"41, 42"}},{"t":"case","label":"United States v. Twitty","cite":"641 F. App’x 801","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/641/801/","by":{"0":"26"}},{"t":"case","label":"United States v. Vonn","cite":"535 U.S. 55","y":2002,"id":"2001/00-973","sc":1,"by":{"0":"10, 17, 18, 19","1":"8, 10, 15, 19, 20, 34","2":"5"},"q":[{"src":"brief","b":1,"text":"because relief on plainerror review is in the discretion of the reviewing court, [petitioner] has the further burden to persuade [the court] that the error seriously affected the fairness, integrity or public reputation of judicial proceedings.","cite":"535 U.S. 55, 63"}]},{"t":"case","label":"United States v. Young","cite":"470 U.S. 1","y":1985,"id":"1984/83-469","sc":1,"by":{"0":"17, 24","1":"8, 15, 17, 18, 24, 31"},"q":[{"src":"brief","b":0,"text":"In reviewing criminal cases, it is particularly important for appellate courts to relive the whole trial imaginatively and not to extract from episodes in isolation abstract questions of evidence and procedure.","cite":"470 U.S. at 16"},{"src":"brief","b":1,"text":"‘[i]t is simply not possible for an appellate court to assess the seriousness of [a] claimed error by any other means.’","cite":"470 U.S. 1, 16"},{"src":"brief","b":1,"text":"tempers the blow of a rigid application of the contemporaneous-objection requirement,","cite":"470 U.S. 1, 15"}]},{"t":"case","label":"Washington v. Texas","cite":"388 U.S. 14","y":1967,"id":"1966/649","sc":1,"by":{"0":"24"},"q":[{"src":"brief","b":0,"text":"own evidence, as well as the prosecution’s . . . evaluated by the jury.","cite":"388 U.S. 14, 20"}]},{"t":"case","label":"Wiborg v. United States","cite":"163 U.S. 632","y":1896,"id":"scdb/1895-269","sc":1,"by":{"0":"11, 12","1":"29","2":"2, 4"},"q":[{"src":"argument","who":"Ms. Guagliardo","text":"And with an insufficiency claim, the question is -- and this goes back to the Court's earliest cases, such as in Clyatt and Wiborg -- what was the information or the evidence introduced before the fact-finder?"},{"src":"argument","who":"Ms. Guagliardo","text":"No, the -- the -- prongs 3 and 4 do not automatically collapse, but it is true that given the nature of the error, when the nature of the error is the insufficient evidence of the defendant's guilt at his trial, some courts, including some of the court -- this Court's earliest cases in Wiborg and Clyatt and other circuit appellate courts, have said there in the ordinary case then, prongs -- if -- if, at prong 3, the outcome has been affected, then that case may ordinarily meet prong 4."}]},{"t":"case","label":"Williamson v. United States","cite":"512 U.S. 594","y":1994,"id":"1993/93-5256","sc":1,"by":{"0":"11"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)","(g)(1)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"by":{"0":"36","1":"37, 41, 37, 41"},"q":[{"src":"brief","b":1,"text":"any person * * * who has been convicted in any court of, a crime punishable by imprisonment for a term exceeding one year.","cite":"18 U.S.C. 922(g)(1)"}]},{"t":"usc","label":"18 U.S.C. § 3661","url":"https://www.law.cornell.edu/uscode/text/18/3661","stext":{"head":"§3661. Use of information for sentencing","paras":[[0,"No limitation shall be placed on the information concerning the background, character, and conduct of a person convicted of an offense which a court of the United States may receive and consider for the purpose of imposing an appropriate sentence."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3661?type=usc&year=mostrecent&link-type=html"},"by":{"0":"37"},"q":[{"src":"brief","b":0,"text":"[n]o limitation shall be placed on the information concerning the background, character, and conduct o f a person convicted of an offense which a court of the United States may receive and consider for the purpose of imposing an appropriate sentence.","cite":"18 U.S.C. § 3661"}]},{"t":"rule","label":"Fed. R. Crim. P. 32","url":"https://www.law.cornell.edu/rules/frcrmp/rule_32","by":{"0":"35, 36, 37"},"q":[{"src":"brief","b":0,"text":"any circumstances affecting the defendant’s behavior that may be helpful in imposing sentence or in correctional treatment.","cite":"Fed. R. Crim. P. 32(d)(2)(A)"}]},{"t":"rule","label":"Fed. R. Crim. P. 52","url":"https://www.law.cornell.edu/rules/frcrmp/rule_52","subs":["(b)"],"by":{"0":"6, 9, 11","2":"1, 5, 5"}},{"t":"rule","label":"Fed. R. Evid. 401","url":"https://www.law.cornell.edu/rules/fre/rule_401","by":{"0":"24"}},{"t":"rule","label":"Fed. R. Evid. 403","url":"https://www.law.cornell.edu/rules/fre/rule_403","by":{"0":"24"}},{"t":"rule","label":"Fed. R. Evid. 704","url":"https://www.law.cornell.edu/rules/fre/rule_704","subs":["(b)"],"by":{"0":"24"}},{"t":"rule","label":"Fed. R. Crim. P. 11","url":"https://www.law.cornell.edu/rules/frcrmp/rule_11","subs":["(h)"],"by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"[I]t is fair to say that the kinds of Rule 11 violations which might be found to constitute harmless error upon direct appeal are fairly limited, as in such instances the matter must be resolved solely on the basis of the Rule 11 transcript and the other portions (e.g., sentencing hearing) of the limited record made in such cases.","cite":"Fed. R. Crim. P. 11(h)"}]},{"t":"case","label":"Brady v. Maryland","cite":"373 U.S. 83","y":1963,"id":"1962/490","sc":1,"by":{"1":"20"}},{"t":"case","label":"Chapman v. California","cite":"386 U.S. 18","y":1967,"id":"1966/95","sc":1,"by":{"1":"21"},"q":[{"src":"brief","b":1,"text":"errors or defects that ha[d] little, if any, likelihood of having changed the result of the trial.","cite":"386 U.S. 18, 22"}]},{"t":"case","label":"Delaware v. Van Arsdall","cite":"475 U.S. 673","y":1986,"id":"1985/84-1279","sc":1,"by":{"1":"18, 28","2":"6"}},{"t":"case","label":"Gardner v. Florida","cite":"430 U.S. 349","y":1977,"id":"1976/74-6593","sc":1,"by":{"1":"35, 36"},"q":[{"src":"brief","b":1,"text":"presume[d] that reports prepared by professional probation officers * * * are generally reliable,","cite":"430 U.S. 349, 359"}]},{"t":"case","label":"Head v. Hargrave","cite":"105 U.S. 45","y":1882,"id":"scdb/1881-157","sc":1,"by":{"1":"39"}},{"t":"case","label":"Henderson v. Kibbe","cite":"431 U.S. 145","y":1977,"id":"1976/75-1906","sc":1,"by":{"1":"24"},"q":[{"src":"brief","b":1,"text":"practice which [this Court] ha[s] criticized as ‘extravagant protection.’","cite":"431 U.S. 145, 154 n.12"}]},{"t":"case","label":"Henderson v. United States","cite":"568 U.S. 266","y":2013,"id":"2012/11-9307","sc":1,"by":{"1":"14"}},{"t":"case","label":"Johnson v. United States","cite":"318 U.S. 189","y":1943,"id":"scdb/1942-124","sc":1,"by":{"1":"17"}},{"t":"case","label":"Jones v. United States","cite":"527 U.S. 373","y":1999,"id":"1998/97-9361","sc":1,"by":{"1":"42"}},{"t":"case","label":"Luce v. United States","cite":"469 U.S. 38","y":1984,"id":"1984/83-912","sc":1,"by":{"1":"15"}},{"t":"case","label":"Old Chief v. United States","cite":"519 U.S. 172","y":1997,"id":"1996/95-6556","sc":1,"by":{"1":"25, 35","2":"14"},"q":[{"src":"brief","b":1,"text":"lure[d] * * * into a sequence of bad character reasoning.","cite":"519 U.S. at 185"},{"src":"argument","who":"Ms. Guagliardo","text":"Chief Justice, and may it please the Court: The question at issue concerns the method an appellate court applies in conducting plain-error review of a defendant's trial and, in particular, what body of evidence an appellate court may rely on to affirm a given -- defendant's conviction at that trial."},{"src":"argument","who":"Justice Thomas","text":"Thank you, Mr. Chief Justice. Counsel, could you -- would you be kind enough to tell me what language from or text from 52(b) that you're relying on?"},{"src":"argument","who":"Ms. Guagliardo","text":"Your Honor, there was the Old Chief stipulation, and when Mr. Greer entered into that stipulation, he did so in accordance with the then-binding precedent."}]},{"t":"case","label":"Parker v. Matthews","cite":"567 U.S. 37","y":2012,"id":"2011/11-845","sc":1,"by":{"1":"39"}},{"t":"case","label":"Puckett v. United States","cite":"556 U.S. 129","y":2009,"id":"2008/07-9712","sc":1,"by":{"1":"13, 14, 15, 22, 24","2":"12, 14"},"q":[{"src":"brief","b":1,"text":"is difficult, ‘as it should be.’","cite":"556 U.S. at 135"},{"src":"brief","b":1,"text":"the opportunity to consider and resolve","cite":"556 U.S. at 134"}]},{"t":"case","label":"Rose v. Clark","cite":"478 U.S. 570","y":1986,"id":"1985/84-1974","sc":1,"by":{"1":"30"}},{"t":"case","label":"Strickland v. Washington","cite":"466 U.S. 668","y":1984,"id":"1983/82-1554","sc":1,"by":{"1":"20"}},{"t":"case","label":"United States v. Atkinson","cite":"297 U.S. 157","y":1936,"id":"scdb/1935-082","sc":1,"by":{"1":"42"}},{"t":"case","label":"United States v. Caudle","cite":"968 F.3d 916","y":2020,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/968/916/","by":{"1":"27"},"q":[{"src":"brief","b":1,"text":"criminal history [that] undoubtedly [would] have provided sufficient evidence to prove that [a defendant] knew his status.","cite":"968 F.3d 916, 922"}]},{"t":"case","label":"United States v. Davila","cite":"569 U.S. 597","y":2013,"id":"2012/12-167","sc":1,"by":{"1":"19"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"denial of counsel of choice, denial of self-representation, denial of a public trial, and failure to convey to a jury that guilt must be proved Page Proof Pending Publication beyond a reasonable doubt.","cite":"569 U. S. 597, 611"}]},{"t":"case","label":"United States v. Frady","cite":"456 U.S. 152","y":1982,"id":"1981/80-1595","sc":1,"by":{"1":"15, 19"},"q":[{"src":"brief","b":1,"text":"our need to encourage all trial participants to seek a fair and accurate trial the first time around [and] our insistence that obvious injustice be promptly redressed.","cite":"456 U.S. 152, 163"},{"src":"brief","b":1,"text":"encourage all trial participants to seek a fair and accurate trial the first time around.","cite":"456 U.S. at 163"}]},{"t":"case","label":"United States v. Games-Perez","cite":"695 F.3d 1104","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/695/1104/","by":{"1":"28"}},{"t":"case","label":"United States v. Gary","cite":"963 F.3d 420","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/963/420/","by":{"1":"39"}},{"t":"case","label":"United States v. Gomez","cite":"705 F.3d 68","y":2013,"url":"https://www.courtlistener.com/c/F.3d/705/68/","by":{"1":"27"},"q":[{"src":"brief","b":1,"text":"To the contrary, the fairness and public reputation of the proceeding would be called into serious question if a defendant were allowed to gain a new trial on the basis of the very procedure he had invited.","cite":"705 F.3d 68, 76"}]},{"t":"case","label":"United States v. Lavalais","cite":"960 F.3d 180","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/960/180/","by":{"1":"39"},"q":[{"src":"brief","b":1,"text":"Convicted felons typically know they’re convicted felons.","cite":"960 F.3d 180, 184"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"will be diffcult for most convicted felons for one simple reason: Convicted felons typically know they're convicted felons.","cite":"960 F. 3d 180, 184"}]},{"t":"case","label":"United States v. Lespier","cite":"725 F.3d 437","y":2013,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/725/437/","by":{"1":"27"},"q":[{"src":"brief","b":1,"text":"In the context of plain error review, an error that was invited by the appellant ‘cannot be viewed as one that affected the fairness, integrity, or public reputation of judicial proceedings.’","cite":"725 F.3d 437, 450"}]},{"t":"case","label":"United States v. Mancillas","cite":"789 Fed. Appx. 549","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./789/549/","by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"aware of his status as a person convicted of an offense punishable by more than a year in prison.","cite":"789 Fed. Appx. 549"}]},{"t":"case","label":"United States v. McGhee","cite":"651 F.3d 153","y":2011,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/651/153/","by":{"1":"37"},"q":[{"src":"brief","b":1,"text":"one of the two variables that fixes the [recommended] sentencing range.","cite":"651 F.3d 153, 155"}]},{"t":"case","label":"United States v. Medley","cite":"972 F.3d 399","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/972/399/","by":{"1":"32"}},{"t":"case","label":"United States v. Miller","cite":"954 F.3d 551","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/954/551/","by":{"1":"25"},"q":[{"src":"brief","b":1,"text":"defendants typically avail[ed] themselves of Old Chief when they ha[d] multiple or damning felony records.","cite":"954 F.3d 551, 559 n.23"}]},{"t":"case","label":"United States v. Moore","cite":"954 F.3d 1322","y":2020,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/954/1322/","by":{"1":"27"}},{"t":"case","label":"United States v. Owens","cite":"966 F.3d 700","y":2020,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/966/700/","by":{"1":"26"}},{"t":"case","label":"United States v. Rosales-Bruno","cite":"789 F.3d 1249","y":2015,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/789/1249/","by":{"1":"37"}},{"t":"case","label":"United States v. Sandford","cite":"814 Fed. Appx. 649","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./814/649/","by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"to prevent the government from offering evidence of his nine prior felonies—a number that itself renders a lack of awareness all but impossible.","cite":"814 Fed. Appx. 649, 653"}]},{"t":"case","label":"United States v. Spencer","cite":"813 Fed. Appx. 385","y":2020,"court":"11th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./813/385/","by":{"1":"26"}},{"t":"case","label":"United States Department of Justice v. Julian","cite":"486 U.S. 1","y":1988,"id":"1987/86-1357","sc":1,"by":{"1":"36"},"q":[{"src":"brief","b":1,"text":"made disclosure of the report mandatory[,] * * * authorized disclosure to both the defendant and defense counsel[,] and * * * required that disclosure be made at a reasonable time before sentencing,","cite":"486 U.S. 1, 10"},{"src":"argument","who":"Ms. Guagliardo","text":"Chief Justice, and may it please the Court: The question at issue concerns the method an appellate court applies in conducting plain-error review of a defendant's trial and, in particular, what body of evidence an appellate court may rely on to affirm a given -- defendant's conviction at that trial."},{"src":"argument","who":"Chief Justice Roberts","text":"Thank you, counsel. Justice Thomas."},{"src":"argument","who":"Justice Thomas","text":"Thank you, Mr. Chief Justice. Counsel, could you -- would you be kind enough to tell me what language from or text from 52(b) that you're relying on?"}]},{"t":"case","label":"Wainwright v. Sykes","cite":"433 U.S. 72","y":1977,"id":"1976/75-1578","sc":1,"by":{"1":"15"}},{"t":"case","label":"Washington v. Recuenco","cite":"548 U.S. 212","y":2006,"id":"2005/05-83","sc":1,"by":{"1":"30"}},{"t":"case","label":"Wong v. Belmontes","cite":"558 U.S. 15","y":2009,"id":"2009/08-1263","sc":1,"by":{"1":"29"}},{"t":"case","label":"Yakus v. United States","cite":"321 U.S. 414","y":1944,"id":"1940-1955/321us414","sc":1,"by":{"1":"13"},"q":[{"src":"brief","b":1,"text":"[c]ourts may for that reason refuse to consider [his] constitutional objection","cite":"321 U.S. at 444"},{"src":"brief","b":1,"text":"constitutional objection * * * inflexible in all cases.","cite":"321 U.S. at 444"}]},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(a)(2)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"by":{"1":"37, 41"},"q":[{"src":"brief","b":1,"text":"shall be fined as provided in this title, imprisoned not more than 10 years, or both.","cite":"18 U.S.C. 924(a)(2)"}]},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)","(a)(1)"],"stext":{"head":"§3553. Imposition of a sentence","paras":[[0,"(a) Factors To Be Considered in Imposing a Sentence.—The court shall impose a sentence sufficient, but not greater than necessary, to comply with the purposes set forth in paragraph (2) of this subsection. The court, in determining the particular sentence to be imposed, shall consider—"],[1,"(1) the nature and circumstances of the offense and the history and characteristics of the defendant;"],[1,"(2) the need for the sentence imposed—"],[2,"(A) to reflect the seriousness of the offense, to promote respect for the law, and to provide just punishment for the offense;"],[2,"(B) to afford adequate deterrence to criminal conduct;"],[2,"(C) to protect the public from further crimes of the defendant; and"],[2,"(D) to provide the defendant with needed educational or vocational training, medical care, or other correctional treatment in the most effective manner;"],[1,"(3) the kinds of sentences available;"],[1,"(4) the kinds of sentence and the sentencing range established for—"],[2,"(A) the applicable category of offense committed by the applicable category of defendant as set forth in the guidelines—"],[3,"(i) issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, subject to any amendments made to such guidelines by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[3,"(ii) that, except as provided in section 3742(g), are in effect on the date the defendant is sentenced; or"],[2,"(B) in the case of a violation of probation or supervised release, the applicable guidelines or policy statements issued by the Sentencing Commission pursuant to section 994(a)(3) of title 28, United States Code, taking into account any amendments made to such guidelines or policy statements by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28);"],[1,"(5) any pertinent policy statement—"],[2,"(A) issued by the Sentencing Commission pursuant to section 994(a)(2) of title 28, United States Code, subject to any amendments made to such policy statement by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[2,"(B) that, except as provided in section 3742(g), is in effect on the date the defendant is sentenced.1"],[1,"(6) the need to avoid unwarranted sentence disparities among defendants with similar records who have been found guilty of similar conduct; and"],[1,"(7) the need to provide restitution to any victims of the offense."],[0,"(b) Application of Guidelines in Imposing a Sentence.—"],[1,"(1) In general.—Except as provided in paragraph (2), the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless the court finds that there exists an aggravating or mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence different from that described. In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission."],[1,"(2) Child crimes and sexual offenses.—"],[2,"(A) 2 Sentencing.—In sentencing a defendant convicted of an offense under section 1201 involving a minor victim, an offense under section 1591, or an offense under chapter 71, 109A, 110, or 117, the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless—"],[3,"(i) the court finds that there exists an aggravating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence greater than that described;"],[3,"(ii) the court finds that there exists a mitigating circumstance of a kind or to a degree, that—"],[4,"(I) has been affirmatively and specifically identified as a permissible ground of downward departure in the sentencing guidelines or policy statements issued under section 994(a) of title 28, taking account of any amendments to such sentencing guidelines or policy statements by Congress;"],[4,"(II) has not been taken into consideration by the Sentencing Commission in formulating the guidelines; and"],[4,"(III) should result in a sentence different from that described; or"],[3,"(iii) the court finds, on motion of the Government, that the defendant has provided substantial assistance in the investigation or prosecution of another person who has committed an offense and that this assistance established a mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence lower than that described."],[0,"In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission, together with any amendments thereto by act of Congress. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission, together with any amendments to such guidelines or policy statements by act of Congress."],[0,"(c) Statement of Reasons for Imposing a Sentence.—The court, at the time of sentencing, shall state in open court the reasons for its imposition of the particular sentence, and, if the sentence—"],[1,"(1) is of the kind, and within the range, described in subsection (a)(4), and that range exceeds 24 months, the reason for imposing a sentence at a particular point within the range; or"],[1,"(2) is not of the kind, or is outside the range, described in subsection (a)(4), the specific reason for the imposition of a sentence different from that described, which reasons must also be stated with specificity in a statement of reasons form issued under section 994(w)(1)(B) of title 28, except to the extent that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32. In the event that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32 the court shall state that such statements were so received and that it relied upon the content of such statements."],[0,"If the court does not order restitution, or orders only partial restitution, the court shall include in the statement the reason therefor. The court shall provide a transcription or other appropriate public record of the court's statement of reasons, together with the order of judgment and commitment, to the Probation System and to the Sentencing Commission,,3 and, if the sentence includes a term of imprisonment, to the Bureau of Prisons."],[0,"(d) Presentence Procedure for an Order of Notice.—Prior to imposing an order of notice pursuant to section 3555, the court shall give notice to the defendant and the Government that it is considering imposing such an order. Upon motion of the defendant or the Government, or on its own motion, the court shall—"],[1,"(1) permit the defendant and the Government to submit affidavits and written memoranda addressing matters relevant to the imposition of such an order;"],[1,"(2) afford counsel an opportunity in open court to address orally the appropriateness of the imposition of such an order; and"],[1,"(3) include in its statement of reasons pursuant to subsection (c) specific reasons underlying its determinations regarding the nature of such an order."],[0,"Upon motion of the defendant or the Government, or on its own motion, the court may in its discretion employ any additional procedures that it concludes will not unduly complicate or prolong the sentencing process."],[0,"(e) Limited Authority To Impose a Sentence Below a Statutory Minimum.—Upon motion of the Government, the court shall have the authority to impose a sentence below a level established by statute as a minimum sentence so as to reflect a defendant's substantial assistance in the investigation or prosecution of another person who has committed an offense. Such sentence shall be imposed in accordance with the guidelines and policy statements issued by the Sentencing Commission pursuant to section 994 of title 28, United States Code."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3553?type=usc&year=mostrecent&link-type=html"},"by":{"1":"37, 41, 37"},"q":[{"src":"brief","b":1,"text":"the history and characteristics of the defendant","cite":"18 U.S.C. 3553(a)(1)"}]},{"t":"case","label":"Cole v. Arkansas","cite":"333 U.S. 196","y":1948,"id":"scdb/1947-046","sc":1,"by":{"2":"8"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"by":{"2":"19"}},{"t":"case","label":"Douglas v. California","cite":"372 U.S. 353","y":1963,"id":"1961/34","sc":1,"by":{"2":"17"}},{"t":"case","label":"Evitts v. Lucey","cite":"469 U.S. 387","y":1985,"id":"1984/83-1378","sc":1,"by":{"2":"17"}},{"t":"case","label":"Galloway v. United States","cite":"319 U.S. 372","y":1943,"id":"scdb/1942-050","sc":1,"by":{"2":"21"}},{"t":"case","label":"Griffin v. Illinois","cite":"351 U.S. 12","y":1956,"id":"1955/95","sc":1,"by":{"2":"17"}},{"t":"case","label":"Jones v. Barnes","cite":"463 U.S. 745","y":1983,"id":"1982/81-1794","sc":1,"by":{"2":"17"},"q":[{"src":"brief","b":2,"text":"no constitutional right to an appeal.","cite":"463 U.S. 745, 751"}]},{"t":"case","label":"United States v. Cotton","cite":"35 U.S. 625","y":2002,"id":"scdb/1836-051","sc":1,"by":{"2":"8, 12, 13, 14"}},{"t":"case","label":"United States v. Games-Perez","cite":"667 F.3d 1136","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/667/1136/","by":{"2":"9"}},{"t":"case","label":"United States v. Titties","cite":"852 F.3d 1257","y":2017,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/852/1257/","by":{"2":"15"}},{"t":"case","label":"United States v. Wiltberger","cite":"18 U.S. 76","y":1820,"id":"scdb/1820-003","sc":1,"by":{"2":"10"}},{"t":"case","label":"Wall v. Kholi","cite":"562 U.S. 545","y":2011,"id":"2010/09-868","sc":1,"by":{"2":"16"}},{"t":"rule","label":"Fed. R. Crim. P. 6","url":"https://www.law.cornell.edu/rules/frcrmp/rule_6","by":{"2":"6"}}]};